r gap-2"><input data-genero="MASCULINO" type="checkbox" class="h-4 w-4 text-[#1d6b3d]"> Hombre</label><label class="flex items-center gap-2"><input data-genero="OTRO" type="checkbox" class="h-4 w-4 text-[#1d6b3d]"> Otro</label></div></div><div data-rango-wrap class="mt-4 hidden rounded-xl border border-[#d9e5dc] bg-white p-4"><p class="text-sm font-medium">Rango de edad</p><div class="mt-3 grid gap-3 sm:grid-cols-[1fr_1fr_auto]"><label class="text-xs text-[#648273]">Desde<input data-rango-min type="number" min="0" max="120" class="mt-1 w-full rounded-lg border border-[#cddbd1] p-2"></label><label class="text-xs text-[#648273]">Hasta<input data-rango-max type="number" min="0" max="120" class="mt-1 w-full rounded-lg border border-[#cddbd1] p-2"></label><button type="button" data-agregar-rango class="self-end rounded-lg bg-[#edf5df] px-3 py-2 text-xs font-semibold text-[#55752c]">Agregar rango</button></div><div data-rangos-lista class="mt-3 space-y-2"></div></div><label data-opciones-wrap class="mt-4 block text-sm font-medium">Opciones de respuesta<span class="ml-1 text-xs font-normal text-[#71847a]">Para selección única, múltiple, sí/no o demográficas. Una opción por línea.</span><textarea data-opciones class="mt-2 w-full rounded-xl border border-[#cddbd1] bg-white p-3 outline-none focus:border-[#23734d]" rows="3" placeholder="Ejemplo: Nunca&#10;A veces&#10;Siempre"></textarea></label><input data-opciones-hidden type="hidden"></fieldset></template>
