<script>
const listaPreguntas = document.getElementById('preguntas-lista'); const plantillaPregunta = document.getElementById('pregunta-template'); let indicePregunta = 0;
const presets = { ESCALA_1_5: ['1', '2', '3', '4', '5'], BOOLEANO: ['Sí', 'No'], HIJOS: ['Sí', 'No'] };
function opcionesActuales(pregunta) { return pregunta.querySelector('[data-opciones]').value.split('\n').map(opcion => opcion.trim()).filter(Boolean); }
function actualizarOpciones(pregunta) { const tipo = pregunta.querySelector('[data-tipo]').value; const opciones = pregunta.querySelector('[data-opciones]'); const genero = [...pregunta.querySelectorAll('[data-genero]:checked')].map(caja => caja.dataset.genero); if (tipo === 'GENERO' && genero.length) opciones.value = genero; if (presets[tipo] && !opciones.value.trim()) opciones.value = presets[tipo].join('\n'); pregunta.querySelector('[data-opciones-wrap]').classList.toggle('hidden', tipo === 'ABIERTA' || tipo === 'NUMERO' || tipo === 'FECHA' || tipo === 'RANGO_EDAD' || tipo === 'GENERO'); pregunta.querySelector('[data-genero-wrap]').classList.toggle('hidden', tipo !== 'GENERO'); pregunta.querySelector('[data-rango-wrap]').classList.toggle('hidden', tipo !== 'RANGO_EDAD'); if (tipo === 'RANGO_EDAD') { opciones.value = [...pregunta.querySelectorAll('[data-rango-label]')].map(rango => rango.dataset.rangoLabel).join('\n'); } }
function agregarRango(pregunta) { const min = pregunta.querySelector('[data-rango-min]').value; const max = pregunta.querySelector('[data-rango-max]').value; if (!min || !max || Number(min) > Number(max)) return; const lista = pregunta.querySelector('[data-rangos-lista]'); const rango = document.createElement('div'); rango.dataset.rangoLabel = ''; rango.dataset.rangoLabel = `${min} a ${max} años`; rango.className = 'flex items-center justify-between rounded-lg bg-[#f0f5ef] px-3 py-2 text-sm text-[#426b53]'; rango.innerHTML = `<span>${min} a ${max} años</span><button type="button" data-quitar-rango class="font-semibold text-[#9a2929]">Quitar</button>`; rango.querySelector('[data-quitar-rango]').addEventListener('click', () => { rango.remove(); actualizarOpciones(pregunta); }); lista.appendChild(rango); pregunta.querySelector('[data-rango-min]').value = ''; pregunta.querySelector('[data-rango-max]').value = ''; actualizarOpciones(pregunta); }
function renumerar() { listaPreguntas.querySelectorAll('.pregunta-titulo').forEach((titulo, posicion) => titulo.textContent = `Pregunta ${posicion + 1}`); }
function agregarPregunta(datos = {}) { const pregunta = plantillaPregunta.content.cloneNode(true).firstElementChild; const indice = indicePregunta++; pregunta.querySelector('[data-enunciado]').name = `preguntas[${indice}][enunciado]`; pregunta.querySelector('[data-tipo]').name = `preguntas[${indice}][tipo_pregunta]`; pregunta.querySelector('[data-tipo]').value = datos.tipo || 'ABIERTA'; pregunta.querySelector('[data-enunciado]').value = datos.enunciado || ''; pregunta.querySelector('[data-obligatoria]').name = `preguntas[${indice}][es_obligatoria]`; pregunta.querySelector('[data-obligatoria]').value = '1'; pregunta.querySelector('[data-opciones]').name = `preguntas[${indice}][opciones]`; pregunta.querySelector('[data-opciones]').value = datos.opciones || ''; pregunta.querySelector('[data-tipo]').addEventListener('change', () => actualizarOpciones(pregunta)); pregunta.querySelectorAll('[data-genero]').forEach(caja => caja.addEventListener('change', () => actualizarOpciones(pregunta))); pregunta.querySelector('[data-agregar-rango]').addEventListener('click', () => agregarRango(pregunta)); pregunta.querySelector('[data-eliminar]').addEventListener('click', () => { pregunta.remove(); renumerar(); }); pregunta.querySelector('[data-duplicar]').addEventListener('click', () => agregarPregunta({ enunciado: pregunta.querySelector('[data-enunciado]').value, tipo: pregunta.querySelector('[data-tipo]').value, opciones: pregunta.querySelector('[data-opciones]').value })); listaPreguntas.appendChild(pregunta); actualizarOpciones(pregunta); renumerar(); }
document.getElementById('agregar-pregunta').addEventListener('click', () => agregarPregunta()); document.querySelector('form').addEventListener('submit', event => { if (!listaPreguntas.children.length || [...listaPreguntas.querySelectorAll('[data-enunciado]')].some(input => !input.value.trim())) { event.preventDefault(); document.getElementById('preguntas-error').classList.remove('hidden'); } }); agregarPregunta();
</script>
